{"filePath":"/Users/noahchae/Downloads/Checkmate/server/src/service/infrastructure/notificationsService.ts","newString":"	handleNotifications = async (monitor: Monitor, monitorStatusResponse: MonitorStatusResponse, decision: MonitorActionDecision) => {
		if (!decision.shouldSendNotification) {
			return false;
		}

		// Send notifications based on decision
		return await this.sendNotifications(monitor, monitorStatusResponse, decision);
	};

	handleEscalationNotifications = async (incidentId: string): Promise<boolean> => {
		try {
			// Get the incident
			const incident = await this.incidentsRepository.findById(incidentId);
			if (!incident || incident.endTime) {
				// Incident doesn't exist or is resolved
				return false;
			}

			// Get the monitor to find associated notifications
			const monitor = await this.monitorsRepository.findById(incident.monitorId);
			if (!monitor) {
				return false;
			}

			const notificationIds = monitor.notifications ?? [];
			if (notificationIds.length === 0) {
				return false;
			}

			// Get all notifications for this monitor
			const notifications = await this.notificationsRepository.findNotificationsByIds(notificationIds);

			// Filter notifications that have escalation enabled
			const escalatedNotifications = notifications.filter(n => n.escalationEnabled && n.escalations?.length);

			if (escalatedNotifications.length === 0) {
				return false;
			}

			// Calculate incident duration in minutes
